<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$cat=(int)($_GET['categorie']??0);$params=[];$where='';if($cat){$where=' WHERE q.categorie_id=:cat';$params['cat']=$cat;}$s=$db->prepare("SELECT q.*,c.libelle categorie,(SELECT COUNT(*) FROM reponses_questionnaire r WHERE r.question_id=q.id) utilisations FROM questions q JOIN categories_risque c ON c.id=q.categorie_id$where ORDER BY c.libelle,q.ordre_affichage");$s->execute($params);$rows=$s->fetchAll();$categories=$db->query('SELECT id,libelle FROM categories_risque ORDER BY libelle')->fetchAll();$title='Questionnaires';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Questionnaires par risque</h1><p class="text-secondary">Questions utilisées pour qualifier le besoin du client</p></div><?php if(in_array($_SESSION['user']['role'],['ADMIN','RESPONSABLE'],true)): ?><a class="btn btn-primary" href="form.php">+ Nouvelle question</a><?php endif; ?></div><form class="filter-bar" method="get"><select class="form-select" name="categorie"><option value="0">Toutes les branches</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= $cat==(int)$c['id']?'selected':'' ?>><?= e($c['libelle']) ?></option><?php endforeach ?></select><button class="btn btn-dark">Filtrer</button></form><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Ordre</th><th>Branche</th><th>Code</th><th>Question</th><th>Réponse</th><th>Obligatoire</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= (int)$r['ordre_affichage'] ?></td><td><span class="badge text-bg-info"><?= e($r['categorie']) ?></span></td><td><?= e($r['code']) ?></td><td><?= e($r['libelle']) ?></td><td><?= e($r['type_reponse']) ?></td><td><?= $r['obligatoire']?'Oui':'Non' ?></td><td class="text-end"><?php if(in_array($_SESSION['user']['role'],['ADMIN','RESPONSABLE'],true)): ?><a class="btn btn-sm btn-outline-primary" href="form.php?id=<?= (int)$r['id'] ?>">Modifier</a><?php endif; ?> <?php if($_SESSION['user']['role']==='ADMIN'): ?><form class="d-inline" method="post" action="delete.php" data-confirm="Supprimer cette question ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Supprimer</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
